questions.text:
Drag and drop the descriptions of IP protocol transmissions from the left onto the correct IP traffic types on the right.
Answer:
TCP: 
+ Sends Transmission in Sequence 
+ Uses a lower transmission rate to ensure reliability 
+ Transmits packet as stream
UDP: 
+ Transmits packets individually 
+ Uses higher transmission rate to support latency-sensitive apps 
+ Transmissions include an 8-byte header
Explanation
UDP is a simpler message-based connectionless protocol. In connectionless protocols, there is no effort made to setup a dedicated end-to-end connection.
…
Datagrams – Packets are sent individually and are guaranteed to be whole if they arrive. Packets have definite bounds and no split or merge into data streams may exist.
According to https://community.cisco.com/t5/networking-documents/udp/ta-p/3114870
TCP is connection-oriented and UDP is connectionless. This means that before sending TCP packets, a connection is established between the server and the client. This process of setting up a connection is called TCP handshaking. The stream of packets is then sent over this connection -> TCP transmits packet as stream.
Reference: https://www.vpnmentor.com/blog/tcp-vs-udp/
document.addEventListener('DOMContentLoaded', function() {
 if (document.getElementById('mar-mask-link')) return;
 // Insert the "Mask Answers" link before Go to comments
 const wrapper = document.createElement('span');
 wrapper.className = 'mask-answers';
 const link = document.createElement('a');
 link.href = '#';
 link.id = 'mar-mask-link';
 link.textContent = 'Hide Correct Answers';
 wrapper.appendChild(link);
 let commentsEl = document.querySelector('span.comments') || document.querySelector('.comments');
 if (commentsEl && commentsEl.parentNode) {
 commentsEl.parentNode.insertBefore(wrapper, commentsEl);
 }
 // --- Mask / Reveal logic ---
 function maskAll() {
 const selectors = ['.ccnacorrectanswers', '.correctanswers'];
 const spans = Array.from(document.querySelectorAll(selectors.join(',')));
 spans.forEach(function(span) {
 if (span.dataset.marMasked) return;
 const parent = span.parentNode;
 if (!parent) return;
 // Gather all nodes after the Answer: span
 let next = span.nextSibling;
 let hasContent = false;
 const wrapperHidden = document.createElement('span');
 wrapperHidden.className = 'mar-answer-hidden';
 wrapperHidden.style.display = 'none';
 while (next) {
 const curr = next;
 next = curr.nextSibling;
 // Check if this node has visible text
 if (curr.nodeType === Node.TEXT_NODE && curr.textContent.trim().length > 0) {
 hasContent = true;
 } else if (curr.nodeType === Node.ELEMENT_NODE) {
 hasContent = true;
 }
 wrapperHidden.appendChild(curr);
 }
 if (hasContent) {
 // Only append wrapper + placeholder if there was content
 parent.appendChild(wrapperHidden);
 const placeholder = document.createElement('span');
 placeholder.className = 'mar-placeholder';
 placeholder.textContent = ' [Click to reveal]';
 placeholder.style.cursor = 'pointer';
 placeholder.style.color = '#555';
 placeholder.style.fontStyle = 'italic';
 parent.appendChild(placeholder);
 span.dataset.marMasked = '1';
 span.style.cursor = 'pointer';
 function reveal() {
 wrapperHidden.style.display = '';
 if (placeholder.parentNode) placeholder.parentNode.removeChild(placeholder);
 delete span.dataset.marMasked;
 span.style.cursor = '';
 span.removeEventListener('click', reveal);
 placeholder.removeEventListener('click', reveal);
 }
 span.addEventListener('click', reveal);
 placeholder.addEventListener('click', reveal);
 }
 });
}
 function revealAll() {
 document.querySelectorAll('.mar-answer-hidden').forEach(el => el.style.display = '');
 document.querySelectorAll('.mar-placeholder').forEach(el => el.remove());
 document.querySelectorAll('.ccnacorrectanswers, .correctanswers').forEach(span => {
 delete span.dataset.marMasked;
 span.style.cursor = '';
 });
 }
 let masked = false;
 link.addEventListener('click', function(e) {
 e.preventDefault();
 if (!masked) {
 maskAll();
 link.textContent = 'Reveal All Answers';
 masked = true;
 } else {
 revealAll();
 link.textContent = 'Hide Correct Answers';
 masked = false;
 }
 });
});

